const idProdutoEditar=new URLSearchParams(location.search).get('id');let produto=null,imagens=[],variantes=[];const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function set(id,v){const e=$(id);if(e)e.value=v??''} function val(id){return $(id)?.value?.trim()||''}
function erro(msg){$('#pe-erro').textContent=msg;$('#pe-erro').hidden=false;window.scrollTo({top:0,behavior:'smooth'})}
function margem(){const c=Number($('#pe-custo').value||0),v=Number($('#pe-venda').value||0),stock=Number($('#pe-stock').value||0),m=v?((v-c)/v)*100:0;$('#pe-margem').textContent=v?`${m.toFixed(1)}%`:'—';$('#pe-lucro').textContent=eur(v-c);$('#pe-lucro-stock').textContent=eur((v-c)*stock);$('#pe-receita-stock').textContent=eur(v*stock);$('#pe-preview-preco').textContent=eur(v);}
function renderGaleria(){const el=$('#pe-galeria');el.innerHTML=imagens.map((x,i)=>`<div class="admin-media-card"><img src="${esc(x.url)}" alt=""><div><strong>${i===0?'Principal':'Imagem '+(i+1)}</strong><button type="button" data-del-img="${i}">Remover</button>${i>0?`<button type="button" data-main-img="${i}">Definir principal</button>`:''}</div></div>`).join('')||'<div class="admin-empty">Nenhuma imagem adicionada.</div>';el.querySelectorAll('[data-del-img]').forEach(b=>b.onclick=()=>{imagens.splice(Number(b.dataset.delImg),1);if(imagens[0])imagens[0].principal=true;renderGaleria();preview()});el.querySelectorAll('[data-main-img]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.mainImg);imagens=imagens.map((x,n)=>({...x,principal:n===i}));imagens=[imagens[i],...imagens.filter((_,n)=>n!==i)];renderGaleria();preview()});}
function renderVariantes(){const el=$('#pe-variantes');if(!variantes.length){el.innerHTML='<div class="admin-empty">Este produto não tem variantes.</div>';return}el.innerHTML='<div class="tabela-scroll"><table><thead><tr><th>Opção</th><th>Valor</th><th>SKU</th><th>VID</th><th>Custo extra</th><th>Venda extra</th><th>Margem</th><th>Stock</th></tr></thead><tbody>'+variantes.map((v,i)=>`<tr><td>${esc(v.nome_opcao)}</td><td>${esc(v.valor_opcao)}</td><td><input data-v="sku" data-i="${i}" value="${esc(v.sku_variante)}"></td><td><input data-v="vid" data-i="${i}" value="${esc(v.id_fornecedor_variante)}"></td><td><input type="number" step="0.01" data-v="costextra" data-i="${i}" value="${Number(v.preco_custo_extra_eur)||0}"></td><td><input type="number" step="0.01" data-v="extra" data-i="${i}" value="${Number(v.preco_extra_eur)||0}"></td><td><input type="number" step="0.1" min="0" max="99.9" data-v="margin" data-i="${i}" value="${Number(v.margem_alvo_pct)||0}"></td><td><input type="number" min="0" data-v="stock" data-i="${i}" value="${Number(v.stock)||0}"></td></tr>`).join('')+'</tbody></table></div>';el.querySelectorAll('[data-v]').forEach(i=>i.oninput=()=>{const v=variantes[Number(i.dataset.i)],k=i.dataset.v;if(k==='stock')v.stock=Number(i.value)||0;else if(k==='extra')v.preco_extra_eur=Number(i.value)||0;else if(k==='costextra')v.preco_custo_extra_eur=Number(i.value)||0;else if(k==='margin')v.margem_alvo_pct=Number(i.value)||0;else if(k==='sku')v.sku_variante=i.value;else v.id_fornecedor_variante=i.value})}
function eur(n){return window.LUMINA_ADMIN?.money(Number(n||0)) || Number(n||0).toLocaleString('pt-PT',{style:'currency',currency:'EUR'})}
function aplicarMargem(){const c=Number($('#pe-custo').value||0),m=Number($('#pe-margem-alvo').value||0);if(c>0&&m>=0&&m<100){$('#pe-venda').value=(c/(1-m/100)).toFixed(2);margem();preview();}}
async function prepararImagem(file){return new Promise((resolve,reject)=>{const img=new Image();const u=URL.createObjectURL(file);img.onload=()=>{const max=1800,s=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*s));c.height=Math.max(1,Math.round(img.naturalHeight*s));c.getContext('2d').drawImage(img,0,0,c.width,c.height);c.toBlob(b=>{URL.revokeObjectURL(u);if(!b)return reject(new Error('Não foi possível otimizar a imagem.'));resolve(new File([b],file.name.replace(/\.[^.]+$/i,'.webp'),{type:'image/webp'}));},'image/webp',.86)};img.onerror=()=>{URL.revokeObjectURL(u);reject(new Error('Imagem inválida.'))};img.src=u})}
async function uploadImagens(){const files=[...($('#pe-upload').files||[])];if(!files.length)return;const st=$('#pe-upload-status');st.textContent='A otimizar e enviar imagens…';try{for(const file of files){const otimizada=await prepararImagem(file);const fd=new FormData();fd.append('imagem',otimizada);const r=await apiFetch('/produtos/admin/upload-imagem',{method:'POST',body:fd});imagens.push({url:r.url,principal:imagens.length===0,ordem:imagens.length});}renderGaleria();preview();st.textContent=`${files.length} imagem(ns) otimizada(s) e enviada(s).`;$('#pe-upload').value='';}catch(e){st.textContent='Erro no upload: '+e.message;}}
async function sincronizarCJ(){try{$('#pe-sync-cj').disabled=true;$('#pe-sync-cj').textContent='A sincronizar…';const r=await apiFetch('/produtos/'+encodeURIComponent(idProdutoEditar)+'/sincronizar-cj',{method:'POST'});alert(`CJ sincronizada. Custo: ${eur(r.precoCustoEUR)} · Venda: ${eur(r.precoVendaEUR)} · Stock: ${r.stock}`);await carregar();}catch(e){erro(e.message)}finally{$('#pe-sync-cj').disabled=false;$('#pe-sync-cj').textContent='Sincronizar CJ';}}
function preview(){const first=imagens[0]?.url;$('#pe-preview-imagem').innerHTML=first?`<img src="${esc(first)}" alt="">`:'<div class="admin-preview-placeholder"></div>';$('#pe-preview-nome').textContent=val('#pe-nome')||'Produto';$('#pe-preview-descricao').textContent=val('#pe-descricao-curta')||'Pré-visualização do cartão do produto.';const tag=val('#pe-etiqueta');$('#pe-preview-etiqueta').hidden=!tag;$('#pe-preview-etiqueta').textContent=tag}
async function carregar(){if(!idProdutoEditar)return erro('Falta o ID do produto na URL.');try{produto=await apiFetch('/produtos/'+encodeURIComponent(idProdutoEditar));set('#pe-nome',produto.nome);set('#pe-categoria',produto.categoria||'Skincare');set('#pe-etiqueta',produto.etiqueta);set('#pe-descricao-curta',produto.descricao_curta||'');set('#pe-descricao',produto.descricao||'');set('#pe-custo',produto.precoCustoEUR);set('#pe-venda',produto.precoVendaEUR);set('#pe-compare',produto.precoCompareEUR||'');set('#pe-margem-alvo',produto.margemAlvoPct||'');set('#pe-imagem-alt',produto.imagemAlt||'');set('#pe-promocao-preco',produto.promocaoPrecoEUR||'');$('#pe-promocao-ativa').checked=!!produto.promocaoAtiva;set('#pe-promocao-inicio',produto.promocao_inicio?String(produto.promocao_inicio).slice(0,16):'');set('#pe-promocao-fim',produto.promocao_fim?String(produto.promocao_fim).slice(0,16):'');set('#pe-beneficios',produto.beneficios);set('#pe-ingredientes',produto.ingredientes);set('#pe-modo-uso',produto.modo_uso);set('#pe-tipo-pele',produto.tipo_pele);set('#pe-tipo-cabelo',produto.tipo_cabelo);set('#pe-fornecedor',produto.fornecedor);set('#pe-id-fornecedor',produto.idFornecedor);set('#pe-sku',produto.skuFornecedor);set('#pe-pais-origem',produto.pais_origem||'');set('#pe-stock',produto.stock);set('#pe-peso',produto.pesoGramas||produto.peso_gramas);set('#pe-link-fornecedor',produto.link_fornecedor);set('#pe-video',produto.video_url);set('#pe-slug',produto.slug);set('#pe-seo-title',produto.seo_title);set('#pe-seo-description',produto.seo_description);$('#pe-ativo').checked=produto.ativo!==false;$('#pe-destaque').checked=!!produto.destaque;imagens=(produto.imagens||[]).map(x=>({...x}));variantes=(produto.variantes||[]).map(x=>({...x}));$('#meta-id').textContent=produto.id;$('#meta-fornecedor').textContent=produto.fornecedor||'—';$('#meta-atualizado').textContent=produto.atualizado_em?new Date(produto.atualizado_em).toLocaleString('pt-PT'):'—';$('#ver-loja').href='../produto.html?id='+encodeURIComponent(produto.id);renderGaleria();renderVariantes();margem();preview()}catch(e){erro(e.message)}}
async function guardar(){try{$('#pe-erro').hidden=true;const body={nome:val('#pe-nome'),categoria:val('#pe-categoria'),descricao:val('#pe-descricao'),descricaoCurta:val('#pe-descricao-curta'),precoCustoEUR:Number(val('#pe-custo'))||0,precoVendaEUR:Number(val('#pe-venda'))||0,precoCompareEUR:Number(val('#pe-compare'))||0,margemAlvoPct:Number(val('#pe-margem-alvo'))||0,promocaoAtiva:$('#pe-promocao-ativa').checked,promocaoPrecoEUR:Number(val('#pe-promocao-preco'))||0,promocaoInicio:val('#pe-promocao-inicio')||null,promocaoFim:val('#pe-promocao-fim')||null,imagemAlt:val('#pe-imagem-alt'),fornecedor:val('#pe-fornecedor'),idFornecedor:val('#pe-id-fornecedor'),skuFornecedor:val('#pe-sku'),paisOrigem:(val('#pe-pais-origem')||'').trim().toUpperCase()||null,stock:Number(val('#pe-stock'))||0,pesoGramas:Number(val('#pe-peso'))||null,linkFornecedor:val('#pe-link-fornecedor'),videoUrl:val('#pe-video'),slug:val('#pe-slug'),seoTitle:val('#pe-seo-title'),seoDescription:val('#pe-seo-description'),beneficios:val('#pe-beneficios'),ingredientes:val('#pe-ingredientes'),modoUso:val('#pe-modo-uso'),tipoPele:val('#pe-tipo-pele'),tipoCabelo:val('#pe-tipo-cabelo'),etiqueta:normalizarEtiquetaAdmin(val('#pe-etiqueta')),ativo:$('#pe-ativo').checked,destaque:$('#pe-destaque').checked,imagens,variantes};if(!body.nome)throw new Error('O nome comercial é obrigatório.');if(body.precoVendaEUR<0)throw new Error('O preço de venda não pode ser negativo.');await apiFetch('/produtos/'+encodeURIComponent(idProdutoEditar),{method:'PUT',body:JSON.stringify(body)});location.href='produtos.html?saved=1'}catch(e){erro(e.message)}}
$('#pe-upload-btn').onclick=uploadImagens;$('#pe-sync-cj').onclick=sincronizarCJ;$('#pe-aplicar-margem').onclick=aplicarMargem;$('#pe-add-imagem').onclick=()=>{const u=val('#pe-imagem-url');if(!u)return;imagens.push({url:u,principal:imagens.length===0,ordem:imagens.length});set('#pe-imagem-url','');renderGaleria();preview()};$('#guardar-topo').onclick=guardar;$('#guardar-side').onclick=guardar;$('#pe-custo').oninput=margem;$('#pe-venda').oninput=()=>{margem();preview()};$('#pe-stock').oninput=margem; window.addEventListener('luminaAdminCurrencyChanged',()=>{margem();preview();});$('#pe-margem-alvo').oninput=()=>{};['#pe-nome','#pe-descricao-curta','#pe-etiqueta'].forEach(s=>$(s).oninput=preview);document.querySelectorAll('.editor-tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.editor-tab').forEach(x=>x.classList.remove('ativa'));document.querySelectorAll('.editor-pane').forEach(x=>x.classList.remove('ativa'));b.classList.add('ativa');document.querySelector(`[data-pane="${b.dataset.tab}"]`).classList.add('ativa')});carregarCategoriasAdmin($('#pe-categoria')).finally(carregar);
